function renderAdminNavIcon(string $key): string
{
    $icons = getAdminNavIcons();

    return $icons[$key] ?? '';
}

function getAdminUserInitials(?array $adminUser): string
{
    $name = trim((string) ($adminUser['name'] ?? $adminUser['username'] ?? 'A'));
    if ($name === '') {
        return 'A';
    }

    $parts = preg_split('/\s+/', $name) ?: [];
    if (count($parts) >= 2) {
        return strtoupper(substr($parts[0], 0, 1) . substr($parts[1], 0, 1));
    }

    return strtoupper(substr($name, 0, 2));
}
